css:
.cvp-profile-poc{--up:#3EE28A;--dn:#FF6B7A;--am:#FFC24D;--ac:#6EA8FF;box-sizing:border-box;width:100%;max-width:400px;background:#0B0F17;border:1px solid #1C2432;border-radius:10px;padding:9px 9px 7px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9px;color:#8B98B0;font-variant-numeric:tabular-nums;outline:none}
.cvp-profile-poc *{box-sizing:border-box}
.cvp-profile-poc:focus-visible{box-shadow:0 0 0 2px rgba(110,168,255,.55)}
.cvp-profile-poc-hd{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:2px 6px}
.cvp-profile-poc-sym{font:700 11px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.03em}
.cvp-profile-poc-sym b{font:500 7.5px ui-monospace,Menlo,Consolas,monospace;color:#56627C;letter-spacing:.06em;margin-left:3px;white-space:nowrap}
.cvp-profile-poc-last{font-size:9px;color:#C9D3E4;white-space:nowrap;text-align:right}
.cvp-profile-poc-last b{color:#E4EBF7;font-size:10px}
.cvp-profile-poc-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px 8px;margin:5px 0 4px;padding:3px 0;border-top:1px solid #1C2432;border-bottom:1px solid #1C2432;font-size:8px;letter-spacing:.05em;color:#5B6883}
.cvp-profile-poc-stats span{display:flex;justify-content:space-between;gap:4px;white-space:nowrap}
.cvp-profile-poc-stats b{color:#D6DFEF;font-weight:600}
.cvp-profile-poc-stats .cvp-profile-poc-pk{color:var(--am)}
.cvp-profile-poc-stats b.cvp-profile-poc-up{color:var(--up)}
.cvp-profile-poc-stats b.cvp-profile-poc-dn{color:var(--dn)}
.cvp-profile-poc-svg{display:block;width:100%;height:auto;cursor:crosshair}
.cvp-profile-poc-svg text{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:7.5px;fill:#5B6883}
.cvp-profile-poc-svg .cvp-profile-poc-tpoc{fill:var(--am);font-weight:700}
.cvp-profile-poc-svg .cvp-profile-poc-tcur{fill:#E4EBF7}
.cvp-profile-poc-cu{stroke:var(--up);fill:#0B0F17;stroke-width:.9}
.cvp-profile-poc-cd{stroke:var(--dn);fill:var(--dn);stroke-width:.9}
.cvp-profile-poc-wk{stroke-width:.9}
.cvp-profile-poc-hb{fill:var(--up)}
.cvp-profile-poc-hs{fill:var(--dn)}
.cvp-profile-poc-out{opacity:.32}
.cvp-profile-poc-in{opacity:.85}
.cvp-profile-poc-pocbox{fill:none;stroke:var(--am);stroke-width:1}
.cvp-profile-poc-pocln{stroke:var(--am);stroke-width:.9;stroke-dasharray:3 2}
.cvp-profile-poc-valn{stroke:var(--ac);stroke-width:.7;stroke-dasharray:1 2;opacity:.8}
.cvp-profile-poc-vabg{fill:rgba(110,168,255,.05)}
.cvp-profile-poc-cur{fill:rgba(228,235,247,.07);stroke:rgba(228,235,247,.28);stroke-width:.5}
.cvp-profile-poc-ax{stroke:#1C2432;stroke-width:1}
.cvp-profile-poc-read{min-height:24px;margin-top:4px;padding:4px 6px;background:#0F1520;border:1px solid #1C2432;border-radius:5px;font-size:8.5px;line-height:1.45;color:#93A2BC}
.cvp-profile-poc-read b{color:#E4EBF7}
.cvp-profile-poc-up{color:var(--up)}
.cvp-profile-poc-dn{color:var(--dn)}
.cvp-profile-poc-tag{display:inline-block;padding:0 4px;border-radius:3px;font-size:7px;letter-spacing:.1em;border:1px solid #2A3650;color:#93A2BC}
.cvp-profile-poc-tag.cvp-profile-poc-tin{border-color:rgba(110,168,255,.5);color:var(--ac)}
.cvp-profile-poc-tag.cvp-profile-poc-tp{border-color:rgba(255,194,77,.6);color:var(--am)}
.cvp-profile-poc-ft{display:flex;flex-wrap:wrap;align-items:center;gap:3px 9px;margin-top:5px;font-size:7px;letter-spacing:.08em;color:#4B5772}
.cvp-profile-poc-ft i{display:inline-block;width:8px;height:4px;border-radius:1px;margin-right:3px;vertical-align:middle}
.cvp-profile-poc-kv{background:rgba(110,168,255,.35);outline:1px dotted var(--ac)}
.cvp-profile-poc-ks{background:var(--dn)}
.cvp-profile-poc-kb{background:var(--up)}
.cvp-profile-poc-keys{margin-left:auto}
@media (prefers-reduced-motion: reduce){.cvp-profile-poc,.cvp-profile-poc *{transition:none;animation:none}}

