var P='cvp-profile-poc';
var svg=root.querySelector('.'+P+'-svg'),rd=root.querySelector('.'+P+'-read');
var st=root.querySelector('.'+P+'-stats'),lastEl=root.querySelector('.'+P+'-last');
var s=91724;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function r2(x){return Math.round(x*100)/100;}
function tm(i){var m=570+i*5,h=Math.floor(m/60),mm=m%60;return (h<10?'0':'')+h+':'+(mm<10?'0':'')+mm;}
function fv(v){return v>=1e6?(v/1e6).toFixed(2)+'M':Math.round(v/1e3)+'k';}
var N=30,BIN=0.05,bars=[],px=131.30,i,k;
for(i=0;i<N;i++){
  var dr=i<6?-0.065:i<13?0.105:i<20?-0.03:0.018;
  var o=px,c=r2(o+dr+(rnd()-.5)*.10);
  var h=r2(Math.max(o,c)+.02+rnd()*.08),l=r2(Math.min(o,c)-.02-rnd()*.08);
  var v=Math.round((i<2?4.2:i<6?2.9:i>26?2.1:1.55)*(0.78+rnd()*.44)*1e4)*100;
  bars.push({o:o,h:h,l:l,c:c,v:v});px=c;
}
function kOf(p){return Math.round(Math.round(p*100)/5);}
var prof={},kMin=1e9,kMax=-1e9,tot=0;
bars.forEach(function(b){
  var lo=kOf(b.l),hi=kOf(b.h),tp=(b.h+b.l+b.c)/3,ws=[],W=0,best=lo,bd=1e9;
  for(k=lo;k<=hi;k++){var d=Math.abs(k*BIN-tp),w=Math.max(.15,1-d/(b.h-b.l+.1));ws.push(w);W+=w;if(d<bd){bd=d;best=k;}}
  var units=b.v/100,used=0,alloc=[];
  for(k=lo;k<=hi;k++){var u=Math.floor(units*ws[k-lo]/W);alloc.push(u);used+=u;}
  alloc[best-lo]+=units-used;
  var tilt=(b.c-b.o)/(b.h-b.l+.01);
  for(k=lo;k<=hi;k++){
    var vol=alloc[k-lo]*100;if(!vol)continue;
    var f=Math.min(.82,Math.max(.18,.5+tilt*.3+(rnd()-.5)*.16)),bu=Math.round(vol*f/100)*100;
    var e=prof[k]||(prof[k]={v:0,b:0,s:0});e.v+=vol;e.b+=bu;e.s+=vol-bu;tot+=vol;
    if(k<kMin)kMin=k;if(k>kMax)kMax=k;
  }
});
function vol(k){return prof[k]?prof[k].v:0;}
var pocK=kMin,maxV=0;
for(k=kMin;k<=kMax;k++)if(vol(k)>maxV){maxV=vol(k);pocK=k;}
var vaLo=pocK,vaHi=pocK,acc=maxV;
while(acc<0.7*tot){
  var up=vaHi<kMax?vol(vaHi+1):-1,dn=vaLo>kMin?vol(vaLo-1):-1;
  if(up<0&&dn<0)break;
  if(up>=dn){vaHi++;acc+=up;}else{vaLo--;acc+=dn;}
}
function pk(k){return (k*BIN).toFixed(2);}
var last=bars[N-1].c,poc=pocK*BIN,dP=r2(last-poc),bp=(last-poc)/poc*1e4;
var sg=function(x,d){return (x>0?'+':x<0?'−':'±')+Math.abs(x).toFixed(d);};
var dc=dP>0?P+'-up':dP<0?P+'-dn':'';
lastEl.innerHTML='LAST <b>'+last.toFixed(2)+'</b>';
st.innerHTML='<span>POC <b class="'+P+'-pk">'+pk(pocK)+'</b></span><span>VAH <b>'+pk(vaHi)+'</b></span><span>VAL <b>'+pk(vaLo)+'</b></span><span>VA <b>'+(acc/tot*100).toFixed(1)+'%</b></span><span>&Sigma;VOL <b>'+fv(tot)+'</b></span><span>vs POC <b class="'+dc+'">'+(dP>0?'▲':dP<0?'▼':'◆')+sg(bp,1)+'bp</b></span>';
var W=300,T=5,B=158,CX=184,PX0=189,PX1=262;
var top=(kMax+.5)*BIN,bot=(kMin-.5)*BIN,nb=kMax-kMin+1,rh=(B-T)/nb;
function Y(p){return T+(top-p)/(top-bot)*(B-T);}
var cur=pocK;
function draw(){
  var g=[],slot=CX/N;
  g.push('<rect class="'+P+'-vabg" x="0" y="'+Y((vaHi+.5)*BIN).toFixed(1)+'" width="'+PX1+'" height="'+((vaHi-vaLo+1)*rh).toFixed(1)+'"/>');
  g.push('<rect class="'+P+'-cur" x="0" y="'+(Y((cur+.5)*BIN)).toFixed(1)+'" width="'+W+'" height="'+rh.toFixed(1)+'"/>');
  g.push('<line class="'+P+'-ax" x1="0" y1="'+B+'" x2="'+PX1+'" y2="'+B+'"/><line class="'+P+'-ax" x1="'+(PX0-2)+'" y1="'+T+'" x2="'+(PX0-2)+'" y2="'+B+'"/>');
  [vaHi+.5,vaLo-.5].forEach(function(e){var yy=Y(e*BIN).toFixed(1);g.push('<line class="'+P+'-valn" x1="0" y1="'+yy+'" x2="'+PX1+'" y2="'+yy+'"/>');});
  var yp=Y(poc).toFixed(1);
  g.push('<line class="'+P+'-pocln" x1="0" y1="'+yp+'" x2="'+PX1+'" y2="'+yp+'"/>');
  bars.forEach(function(b,i){
    var x=(i+.5)*slot,cl=b.c>=b.o?P+'-cu':P+'-cd',y1=Y(Math.max(b.o,b.c)),y2=Y(Math.min(b.o,b.c));
    g.push('<line class="'+cl+' '+P+'-wk" x1="'+x.toFixed(1)+'" y1="'+Y(b.h).toFixed(1)+'" x2="'+x.toFixed(1)+'" y2="'+Y(b.l).toFixed(1)+'"/>');
    g.push('<rect class="'+cl+'" x="'+(x-1.8).toFixed(1)+'" y="'+y1.toFixed(1)+'" width="3.6" height="'+Math.max(.8,y2-y1).toFixed(1)+'"/>');
  });
  for(k=kMin;k<=kMax;k++){
    var e=prof[k],yy=Y((k+.5)*BIN)+.6,hh=Math.max(1,rh-1.2);
    if(e){
      var L=e.v/maxV*(PX1-PX0),ls=e.s/e.v*L,cls=(k>=vaLo&&k<=vaHi)?P+'-in':P+'-out';
      g.push('<rect class="'+P+'-hs '+cls+'" x="'+PX0+'" y="'+yy.toFixed(1)+'" width="'+ls.toFixed(1)+'" height="'+hh.toFixed(1)+'"/>');
      g.push('<rect class="'+P+'-hb '+cls+'" x="'+(PX0+ls).toFixed(1)+'" y="'+yy.toFixed(1)+'" width="'+(L-ls).toFixed(1)+'" height="'+hh.toFixed(1)+'"/>');
      if(k===pocK)g.push('<rect class="'+P+'-pocbox" x="'+(PX0-.5)+'" y="'+(yy-.5).toFixed(1)+'" width="'+(L+1).toFixed(1)+'" height="'+(hh+1).toFixed(1)+'"/>');
    }
    if((k-pocK)%4===0||k===cur){
      var tc=k===pocK?P+'-tpoc':k===cur?P+'-tcur':'';
      g.push('<text class="'+tc+'" x="298" y="'+(Y(k*BIN)+2.6).toFixed(1)+'" text-anchor="end">'+pk(k)+'</text>');
    }
  }
  [0,12,24].forEach(function(i){g.push('<text x="'+(i?((i+.5)*slot).toFixed(1):0)+'" y="168" text-anchor="'+(i?'middle':'start')+'">'+tm(i)+'</text>');});
  g.push('<text x="'+PX0+'" y="168">VOL@PX</text>');
  svg.innerHTML=g.join('');
  var e2=prof[cur]||{v:0,b:0,s:0},bp2=e2.v?Math.round(e2.b/e2.v*100):0;
  var inVa=cur>=vaLo&&cur<=vaHi;
  rd.innerHTML='<b>'+pk(cur)+'</b> <span>'+((cur*5-2)/100).toFixed(2)+'&ndash;'+((cur*5+2)/100).toFixed(2)+'</span> &middot; <b>'+fv(e2.v)+'</b> sh &middot; '+(e2.v/tot*100).toFixed(1)+'% of vol '+
    (cur===pocK?'<span class="'+P+'-tag '+P+'-tp">POC</span> ':'')+'<span class="'+P+'-tag'+(inVa?' '+P+'-tin':'')+'">'+(inVa?'IN VA':'OUT VA')+'</span><br>'+
    (e2.v?'<span class="'+P+'-up">&#9650; BUY '+fv(e2.b)+' '+bp2+'%</span> / <span class="'+P+'-dn">&#9660; SELL '+fv(e2.s)+' '+(100-bp2)+'%</span> &middot; &Delta; '+sg(e2.b-e2.s,0).replace(/(\d)(?=(\d{3})+$)/g,'$1,'):'no prints at level');
}
function setCur(k2){cur=Math.max(kMin,Math.min(kMax,k2));draw();}
root.addEventListener('keydown',function(e){
  var m={ArrowUp:1,ArrowDown:-1,PageUp:5,PageDown:-5}[e.key];
  if(m){e.preventDefault();setCur(cur+m);}
  else if(e.key==='Home'){e.preventDefault();setCur(pocK);}
});
svg.addEventListener('mousemove',function(e){
  var r=svg.getBoundingClientRect();if(!r.height)return;
  var yy=(e.clientY-r.top)/r.height*172;if(yy<T||yy>B)return;
  var p=top-(yy-T)/(B-T)*(top-bot),k2=kOf(p);
  if(k2!==cur)setCur(k2);
});
draw();

