js:
var P='cvp-anchored-vwap';
var svg=root.querySelector('.'+P+'-svg'),r1=root.querySelector('.'+P+'-r1'),r2el=root.querySelector('.'+P+'-r2'),ft=root.querySelector('.'+P+'-ft');
var btns=root.querySelectorAll('.'+P+'-b');
var s=557311;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function r2(x){return Math.round(x*100)/100;}
function tm(i){var m=570+i*5,h=Math.floor(m/60),mm=m%60;return (h<10?'0':'')+h+':'+(mm<10?'0':'')+mm;}
function cm(n){return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
var N=60,bars=[],px=741.20,i;
for(i=0;i<N;i++){
  var dr=i<4?0.95:i<22?-0.52:0.15;
  var o=px,c=r2(o+dr+(rnd()-.5)*1.1);
  var h=r2(Math.max(o,c)+.05+rnd()*.45),l=r2(Math.min(o,c)-.05-rnd()*.45);
  var v=Math.round((0.12+0.5*Math.exp(-i/5)+(i>55?0.09:0))*(0.8+rnd()*.4)*10370)*100;
  bars.push({o:o,h:h,l:l,c:c,v:v,tp:(h+l+c)/3});px=c;
}
var hod=0,lod=0;
for(i=1;i<N;i++){if(bars[i].h>bars[hod].h)hod=i;if(bars[i].l<bars[lod].l)lod=i;}
var anchors={open:0,lod:lod,hod:hod},aKey='lod',a=lod,cur=N-1;
var vw=[],sd=[],cv=[],cn=[];
function calc(){
  var S0=0,S1=0,S2=0;vw=[];sd=[];cv=[];cn=[];
  for(var j=0;j<N;j++){
    if(j<a){vw.push(null);sd.push(null);cv.push(0);cn.push(0);continue;}
    var b=bars[j];S0+=b.v;S1+=b.tp*b.v;S2+=b.tp*b.tp*b.v;
    var m=S1/S0;vw.push(m);sd.push(Math.sqrt(Math.max(0,S2/S0-m*m)));cv.push(S0);cn.push(S1);
  }
}
var X0=2,X1=258,T=6,B=104,VT=110,VB=134;
function X(j){return X0+j*(X1-X0)/(N-1);}
function draw(){
  calc();
  var lo=1e9,hi=-1e9,j;
  for(j=0;j<N;j++){lo=Math.min(lo,bars[j].l);hi=Math.max(hi,bars[j].h);if(vw[j]!==null){lo=Math.min(lo,vw[j]-2*sd[j]);hi=Math.max(hi,vw[j]+2*sd[j]);}}
  var pad=(hi-lo)*.05;lo-=pad;hi+=pad;
  function Y(p){return T+(hi-p)/(hi-lo)*(B-T);}
  var g=[],step=(hi-lo)>8?2:(hi-lo)>4?1:0.5;
  for(var gp=Math.ceil(lo/step)*step;gp<=hi;gp+=step){var gy=Y(gp).toFixed(1);g.push('<line class="'+P+'-grid" x1="0" y1="'+gy+'" x2="'+X1+'" y2="'+gy+'"/><text x="298" y="'+(+gy+2.5)+'" text-anchor="end">'+gp.toFixed(step<1?1:0)+'</text>');}
  function band(k,cls){
    var up=[],dn=[];
    for(j=a;j<N;j++){up.push(X(j).toFixed(1)+','+Y(vw[j]+k*sd[j]).toFixed(1));dn.unshift(X(j).toFixed(1)+','+Y(vw[j]-k*sd[j]).toFixed(1));}
    return '<polygon class="'+cls+'" points="'+up.concat(dn).join(' ')+'"/>';
  }
  function line(f,cls,from){var pts=[];for(j=from;j<N;j++)pts.push(X(j).toFixed(1)+','+Y(f(j)).toFixed(1));return '<polyline class="'+cls+'" points="'+pts.join(' ')+'"/>';}
  g.push(band(2,P+'-b2'),band(1,P+'-b1'));
  [2,-2].forEach(function(k){g.push(line(function(j){return vw[j]+k*sd[j];},P+'-s2',a));});
  [1,-1].forEach(function(k){g.push(line(function(j){return vw[j]+k*sd[j];},P+'-s1',a));});
  if(a>0){var pre=[];for(j=0;j<=a;j++)pre.push(X(j).toFixed(1)+','+Y(bars[j].c).toFixed(1));g.push('<polyline class="'+P+'-pre" points="'+pre.join(' ')+'"/>');}
  g.push(line(function(j){return bars[j].c;},P+'-px',a));
  g.push(line(function(j){return vw[j];},P+'-vw',a));
  var mv=0;for(j=0;j<N;j++)mv=Math.max(mv,bars[j].v);
  for(j=0;j<N;j++){var vh=bars[j].v/mv*(VB-VT);g.push('<rect class="'+(bars[j].c>=bars[j].o?P+'-vu':P+'-vd')+(j<a?' '+P+'-vo':'')+'" x="'+(X(j)-1.6).toFixed(1)+'" y="'+(VB-vh).toFixed(1)+'" width="3.2" height="'+vh.toFixed(1)+'"/>');}
  var ax=X(a).toFixed(1);
  g.push('<line class="'+P+'-an" x1="'+ax+'" y1="'+T+'" x2="'+ax+'" y2="'+VB+'"/><text class="'+P+'-at" x="'+(+ax+2)+'" y="'+(T+6)+'"'+(a>N*.7?' text-anchor="end" dx="-4"':'')+'>A '+tm(a)+'</text>');
  var lv=vw[N-1],ly=Y(lv);
  g.push('<rect class="'+P+'-tgb" x="259" y="'+(ly-4.5).toFixed(1)+'" width="40" height="9" rx="1.5"/><text class="'+P+'-tg" x="297" y="'+(ly+2.6).toFixed(1)+'" text-anchor="end">'+lv.toFixed(2)+'</text>');
  var cx=X(cur).toFixed(1);
  g.push('<line class="'+P+'-cu" x1="'+cx+'" y1="'+T+'" x2="'+cx+'" y2="'+VB+'"/><circle class="'+P+'-dot" cx="'+cx+'" cy="'+Y(bars[cur].c).toFixed(1)+'" r="1.8"/>');
  [0,12,24,36,48].forEach(function(t){g.push('<text x="'+X(t).toFixed(1)+'" y="145" text-anchor="'+(t?'middle':'start')+'">'+tm(t)+'</text>');});
  svg.innerHTML=g.join('');
  btns.forEach(function(b){var on=b.getAttribute('data-a')===aKey;b.classList.toggle(P+'-on',on);b.setAttribute('aria-pressed',on?'true':'false');});
  var bc=bars[cur];
  if(cur<a){
    r1.innerHTML=tm(cur)+' C <b>'+bc.c.toFixed(2)+'</b> &middot; before anchor '+tm(a);
    r2el.innerHTML='<span>No AVWAP yet &mdash; press &crarr; to anchor here</span>';
    ft.innerHTML='ANCHOR <b>'+tm(a)+' '+aKey.toUpperCase()+'</b>';
    return;
  }
  var m=vw[cur],sg=sd[cur],z=sg>1e-9?(bc.c-m)/sg:0,bp=(bc.c-m)/m*1e4;
  var zone=sg<1e-9?'&sigma; n/a (1 bar)':z>=2?'ABOVE +2&sigma;':z>=1?'+1&sigma;&hellip;+2&sigma;':z>-1?'INSIDE &plusmn;1&sigma;':z>-2?'&minus;1&sigma;&hellip;&minus;2&sigma;':'BELOW &minus;2&sigma;';
  var cls=z>0?P+'-up':z<0?P+'-dn':'',ar=z>0?'&#9650;':z<0?'&#9660;':'&#9670;';
  function sgn(x,d){return (x>0?'+':x<0?'&minus;':'&plusmn;')+Math.abs(x).toFixed(d);}
  r1.innerHTML=tm(cur)+' C <b>'+bc.c.toFixed(2)+'</b> &middot; AVWAP <b class="'+P+'-vwv">'+m.toFixed(3)+'</b> &middot; &sigma; <b>'+sg.toFixed(3)+'</b>';
  r2el.innerHTML='<span class="'+cls+'">'+ar+' z '+sgn(z,2)+'&sigma; &middot; '+sgn(bp,1)+' bp vs AVWAP</span> <span class="'+P+'-zt">'+zone+'</span>';
  ft.innerHTML='ANCHOR <b>'+tm(a)+' '+(aKey==='cur'?'CURSOR':aKey.toUpperCase())+'</b> &middot; BARS <b>'+(cur-a+1)+'</b> &middot; &Sigma;V <b>'+cm(cv[cur])+'</b> &middot; &Sigma;N <b>$'+cm((cn[cur]/1e6).toFixed(2))+'M</b> &rarr; N/V <b>'+(cn[cur]/cv[cur]).toFixed(3)+'</b>';
}
function setA(k){aKey=k;if(k!=='cur')a=anchors[k];else a=cur;draw();}
btns.forEach(function(b){b.addEventListener('click',function(){setA(b.getAttribute('data-a'));});});
root.addEventListener('keydown',function(e){
  var st=e.shiftKey?5:1;
  if(e.key==='ArrowLeft'){e.preventDefault();cur=Math.max(0,cur-st);draw();}
  else if(e.key==='ArrowRight'){e.preventDefault();cur=Math.min(N-1,cur+st);draw();}
  else if(e.key==='Home'){e.preventDefault();cur=0;draw();}
  else if(e.key==='End'){e.preventDefault();cur=N-1;draw();}
  else if(e.key==='Enter'&&e.target===root){e.preventDefault();setA('cur');}
  else if(e.key==='1')setA('open');else if(e.key==='2')setA('lod');else if(e.key==='3')setA('hod');
});
svg.addEventListener('mousemove',function(e){var r=svg.getBoundingClientRect();if(!r.width)return;var xx=(e.clientX-r.left)/r.width*300;var j=Math.round((xx-X0)/(X1-X0)*(N-1));j=Math.max(0,Math.min(N-1,j));if(j!==cur){cur=j;draw();}});
svg.addEventListener('click',function(){setA('cur');});
draw();

