js:
var P='cvp-footprint-grid';
var grid=root.querySelector('.'+P+'-grid'),tot=root.querySelector('.'+P+'-tot'),sum=root.querySelector('.'+P+'-sum');
var mbs=root.querySelectorAll('.'+P+'-m');
var s=240613;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function cm(n){var a=Math.abs(n);return (n<0?'−':'')+String(a).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function sg(n){return (n>0?'+':'')+cm(n);}
var BASE=6712.00,TK=0.25,NL=14,CVD0=2140,IMB=3,MINQ=20;
var spec=[['10:00',5,8,2,7],['10:05',7,9,4,4],['10:10',4,11,3,10],['10:15',10,13,9,12],['10:20',12,12,7,8]];
function lp(l){return (BASE+l*TK).toFixed(2);}
var bars=spec.map(function(q){
  var o=q[1],h=q[2],l=q[3],c=q[4],dir=c>o?1:c<o?-1:0,bid={},ask={};
  var pc=Math.round((o+c)/2+(rnd()-.5)),sig=Math.max(1.2,(h-l)/2.6);
  for(var k=l;k<=h;k++){
    var t=Math.round((45+540*Math.exp(-(k-pc)*(k-pc)/(2*sig*sig)))*(0.72+rnd()*.56));
    var f=Math.min(.85,Math.max(.15,.5+dir*.1+(rnd()-.5)*.34)),a=Math.round(t*f);
    ask[k]=a;bid[k]=t-a;
  }
  return {t:q[0],o:o,h:h,l:l,c:c,bid:bid,ask:ask};
});
[[2,[6,7,8],1],[4,[9,10],-1]].forEach(function(inj){
  var b=bars[inj[0]];
  inj[1].forEach(function(k){
    if(inj[2]>0){b.bid[k-1]=Math.max(6,Math.round(b.bid[k-1]*.3));b.ask[k]=Math.max(b.ask[k],Math.ceil(b.bid[k-1]*3.3)+14);}
    else{b.ask[k+1]=Math.max(6,Math.round(b.ask[k+1]*.3));b.bid[k]=Math.max(b.bid[k],Math.ceil(b.ask[k+1]*3.3)+14);}
  });
});
var maxD=1,cvd=CVD0,gLo=99,gHi=-1;bars.forEach(function(b){gLo=Math.min(gLo,b.l);gHi=Math.max(gHi,b.h);});
bars.forEach(function(b){
  b.vol=0;b.d=0;b.imbB={};b.imbS={};b.nb=0;b.ns=0;var pv=-1;
  for(var k=b.l;k<=b.h;k++){
    var v=b.bid[k]+b.ask[k],d=b.ask[k]-b.bid[k];b.vol+=v;b.d+=d;
    if(v>pv){pv=v;b.poc=k;}
    maxD=Math.max(maxD,Math.abs(d));
    if(k-1>=b.l&&b.ask[k]>=MINQ&&b.ask[k]>=IMB*Math.max(1,b.bid[k-1])){b.imbB[k]=1;b.nb++;}
    if(k+1<=b.h&&b.bid[k]>=MINQ&&b.bid[k]>=IMB*Math.max(1,b.ask[k+1])){b.imbS[k]=1;b.ns++;}
  }
  cvd+=b.d;b.cvd=cvd;
  function stack(m){var run=0,best=0;for(var k=b.l;k<=b.h;k++){run=m[k]?run+1:0;best=Math.max(best,run);}return best;}
  b.stB=stack(b.imbB);b.stS=stack(b.imbS);
});
var mode='ba',sel=bars.length-1,lastL=bars[bars.length-1].c;
function draw(){
  var h=['<div class="'+P+'-h" style="cursor:default">PRICE</div>'];
  bars.forEach(function(b,i){
    var ch=(b.c-b.o)*TK,ar=ch>0?'&#9650;':ch<0?'&#9660;':'&#9670;',cl=ch>0?P+'-up':ch<0?P+'-dn':'';
    h.push('<div class="'+P+'-h'+(i===sel?' '+P+'-sel':'')+'" data-i="'+i+'" role="columnheader">'+b.t+'<em class="'+cl+'">'+ar+(ch>0?'+':ch<0?'−':'')+Math.abs(ch).toFixed(2)+'</em></div>');
  });
  for(var k=gHi;k>=gLo;k--){
    h.push('<div class="'+P+'-p'+(k===lastL?' '+P+'-last':'')+'">'+lp(k)+'</div>');
    bars.forEach(function(b,i){
      var c=P+'-c'+(i===sel?' '+P+'-cs':'');
      if(k<b.l||k>b.h){h.push('<div class="'+c+' '+P+'-x"></div>');return;}
      var bd=b.bid[k],ak=b.ask[k],d=ak-bd,al=(0.07+0.42*Math.abs(d)/maxD).toFixed(3);
      var bg=d>0?'rgba(62,226,138,'+al+')':d<0?'rgba(255,107,122,'+al+')':'transparent';
      if(k>=Math.min(b.o,b.c)&&k<=Math.max(b.o,b.c))c+=' '+P+'-bd';
      if(k===b.poc)c+=' '+P+'-poc';
      if(b.imbB[k])c+=' '+P+'-mb';if(b.imbS[k])c+=' '+P+'-ms';
      var tx=mode==='ba'?'<i class="'+(b.imbS[k]?P+'-is':'')+'">'+bd+'</i>&times;<i class="'+(b.imbB[k]?P+'-ib':'')+'">'+ak+'</i>':mode==='d'?sg(d):cm(bd+ak);
      var lab=lp(k)+' '+b.t+': bid '+bd+', ask '+ak+', delta '+sg(d)+(b.imbB[k]?', buy imbalance':'')+(b.imbS[k]?', sell imbalance':'')+(k===b.poc?', bar POC':'');
      h.push('<div class="'+c+'" style="background-color:'+bg+'" role="gridcell" aria-label="'+lab+'">'+tx+'</div>');
    });
  }
  grid.innerHTML=h.join('');
  var t=[];
  [['VOL',function(b){return cm(b.vol);}],['&Delta;',function(b){return '<span class="'+(b.d>0?P+'-up':b.d<0?P+'-dn':'')+'">'+sg(b.d)+'</span>';}],
   ['&Delta;%',function(b){var p=b.d/b.vol*100;return '<span class="'+(p>0?P+'-up':p<0?P+'-dn':'')+'">'+(p>0?'+':p<0?'−':'')+Math.abs(p).toFixed(1)+'</span>';}],
   ['CVD',function(b){return sg(b.cvd);}]].forEach(function(r){
    t.push('<div class="'+P+'-tl">'+r[0]+'</div>');
    bars.forEach(function(b,i){t.push('<div class="'+P+'-tv'+(i===sel?' '+P+'-sel':'')+'">'+r[1](b)+'</div>');});
  });
  tot.innerHTML=t.join('');
  var b=bars[sel],st=b.stB>=3?' &middot; <span class="'+P+'-up">STACKED BUY &times;'+b.stB+'</span>':b.stS>=3?' &middot; <span class="'+P+'-dn">STACKED SELL &times;'+b.stS+'</span>':b.stS>=2?' &middot; <span class="'+P+'-dn">sell imb &times;'+b.stS+' stacked</span>':'';
  sum.innerHTML='<b>'+b.t+'</b> O <b>'+lp(b.o)+'</b> H <b>'+lp(b.h)+'</b> L <b>'+lp(b.l)+'</b> C <b>'+lp(b.c)+'</b><br>VOL <b>'+cm(b.vol)+'</b> &middot; &Delta; <b class="'+(b.d>0?P+'-up':b.d<0?P+'-dn':'')+'">'+sg(b.d)+'</b> &middot; POC <b>'+lp(b.poc)+'</b> &middot; imb <span class="'+P+'-up">&#9650;'+b.nb+'</span>/<span class="'+P+'-dn">&#9660;'+b.ns+'</span>'+st;
  mbs.forEach(function(m){var on=m.getAttribute('data-m')===mode;m.classList.toggle(P+'-on',on);m.setAttribute('aria-pressed',on?'true':'false');});
}
grid.addEventListener('click',function(e){var hd=e.target.closest('.'+P+'-h[data-i]');if(hd){sel=+hd.getAttribute('data-i');draw();}});
mbs.forEach(function(m){m.addEventListener('click',function(){mode=m.getAttribute('data-m');draw();});});
root.addEventListener('keydown',function(e){
  if(e.key==='ArrowLeft'){e.preventDefault();sel=Math.max(0,sel-1);draw();}
  else if(e.key==='ArrowRight'){e.preventDefault();sel=Math.min(bars.length-1,sel+1);draw();}
  else{var m={b:'ba',d:'d',v:'v'}[e.key.toLowerCase()];if(m){mode=m;draw();}}
});
draw();

