.cvp-delta-divergence{--up:#3EE28A;--dn:#FF6B7A;--am:#FFC24D;--ac:#6EA8FF;box-sizing:border-box;width:100%;max-width:400px;background:#0B0F17;border:1px solid #1C2432;border-radius:10px;padding:9px 9px 7px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9px;color:#8B98B0;font-variant-numeric:tabular-nums;outline:none}
.cvp-delta-divergence *{box-sizing:border-box}
.cvp-delta-divergence:focus-visible{box-shadow:0 0 0 2px rgba(110,168,255,.5)}
.cvp-delta-divergence-hd{display:flex;justify-content:space-between;align-items:center;gap:6px}
.cvp-delta-divergence-sym{font:700 11px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.03em;white-space:nowrap}
