.cvp-delta-divergence-live{display:flex;align-items:center;gap:4px;padding:2px 6px;font:600 7.5px/1.3 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.1em;color:var(--up);background:#0E1A14;border:1px solid rgba(62,226,138,.35);border-radius:3px;cursor:pointer}
.cvp-delta-divergence-live i{width:5px;height:5px;border-radius:50%;background:var(--up);animation:cvp-delta-divergence-pulse 1.4s ease-in-out infinite}
.cvp-delta-divergence-live[aria-pressed="true"]{color:#93A2BC;background:#111826;border-color:#2A3650}
.cvp-delta-divergence-live[aria-pressed="true"] i{background:#56627C;animation:none}
.cvp-delta-divergence-live:focus-visible{outline:1px solid var(--ac);outline-offset:1px}
@keyframes cvp-delta-divergence-pulse{0%,100%{opacity:1}50%{opacity:.25}}
.cvp-delta-divergence-sig{margin:5px 0 3px;padding:3px 6px;border-radius:4px;font-size:8px;letter-spacing:.03em;background:#111826;border:1px solid #1C2432;color:#7C8AA5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
