.cvp-delta-divergence-sig.cvp-delta-divergence-bear{background:rgba(255,107,122,.08);border-color:rgba(255,107,122,.4);color:#F3C2C8}
.cvp-delta-divergence-sig.cvp-delta-divergence-bear b{color:var(--dn)}
.cvp-delta-divergence-sig.cvp-delta-divergence-bull{background:rgba(62,226,138,.07);border-color:rgba(62,226,138,.4);color:#BDEFD3}
.cvp-delta-divergence-sig.cvp-delta-divergence-bull b{color:var(--up)}
.cvp-delta-divergence-svg{display:block;width:100%;height:auto}
