var P='cvp-delta-divergence';
var svg=root.querySelector('.'+P+'-svg'),sigEl=root.querySelector('.'+P+'-sig'),rd=root.querySelector('.'+P+'-read'),btn=root.querySelector('.'+P+'-live');
var s=447101;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function r2(x){return Math.round(x*100)/100;}
function cm(n){var a=Math.abs(n);return String(a).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function sg(n){return (n>0?'+':n<0?'−':'±')+cm(n);}
function hm(t){var h=Math.floor(t/60)%24,m=t%60;return (h<10?'0':'')+h+':'+(m<10?'0':'')+m;}
var TK=0.01,WIN=40,K=3,base={buy:512400,sell:512580},bars=[];
var kp=[[0,71.20],[14,71.62],[22,71.38],[33,71.71],[39,71.60]],seg=[[9,20],[7,-30],[1.2,-25],[6,-20]];
var prev=71.18,i;
for(i=0;i<WIN;i++){
  var j=0;while(j<kp.length-2&&i>=kp[j+1][0])j++;
  var A=kp[j],Bk=kp[j+1],tg=A[1]+(Bk[1]-A[1])*(i-A[0])/(Bk[0]-A[0]);
  var o=prev,c=r2(tg+(rnd()-.5)*.03),h=r2(Math.max(o,c)+rnd()*.025),l=r2(Math.min(o,c)-rnd()*.025);
  var vol=Math.round(900+rnd()*1300+Math.abs(c-o)/TK*22);
  var d=Math.round(seg[j][0]*(c-o)/TK+seg[j][1]+(rnd()-.5)*50);d=Math.max(-vol*.8,Math.min(vol*.8,d));
  var buy=Math.round((vol+d)/2);
  bars.push({t:612+i,o:o,h:h,l:l,c:c,buy:buy,sell:vol-buy});prev=c;
}
function pivots(arr,hi){
  var out=[];
  for(var i=K;i<arr.length-K;i++){
    var ok=true;
    for(var j=i-K;j<=i+K&&ok;j++){if(j===i)continue;if(hi?(arr[j]>arr[i]||(arr[j]===arr[i]&&j<i)):(arr[j]<arr[i]||(arr[j]===arr[i]&&j<i)))ok=false;}
    if(ok)out.push(i);
  }
  return out;
}
function draw(){
  var n=bars.length,cvd=[],run=base.buy-base.sell,tb=base.buy,ts=base.sell;
  bars.forEach(function(b){run+=b.buy-b.sell;tb+=b.buy;ts+=b.sell;cvd.push(run);});
  var lo=1e9,hi=-1e9,clo=0,chi=0;
  bars.forEach(function(b,i){lo=Math.min(lo,b.l);hi=Math.max(hi,b.h);clo=Math.min(clo,cvd[i]);chi=Math.max(chi,cvd[i]);});
  var pp=(hi-lo)*.08+.005;lo-=pp;hi+=pp;var cp=(chi-clo)*.1+10;clo-=cp;chi+=cp;
  var X1=262,T=4,PB=90,CT=98,CB=152,sl=X1/WIN;
  function X(i){return (i+.5)*sl;}
  function Y(p){return T+(hi-p)/(hi-lo)*(PB-T);}
  function YC(v){return CT+(chi-v)/(chi-clo)*(CB-CT);}
  var g=[],st=(hi-lo)>.3?.1:.05,ly=Y(bars[n-1].c);
  for(var gp=Math.ceil(lo/st)*st;gp<=hi;gp+=st){var gy=Y(gp);g.push('<line class="'+P+'-grid" x1="0" y1="'+gy.toFixed(1)+'" x2="'+X1+'" y2="'+gy.toFixed(1)+'"/>'+(Math.abs(gy-ly)<8||gy<T+3?'':'<text x="298" y="'+(gy+2.5).toFixed(1)+'" text-anchor="end">'+gp.toFixed(2)+'</text>'));}
  var zy=YC(0).toFixed(1);
  g.push('<line class="'+P+'-zero" x1="0" y1="'+zy+'" x2="'+X1+'" y2="'+zy+'"/><text x="298" y="'+(+zy+2.5)+'" text-anchor="end">0</text>');
  g.push('<text x="298" y="'+(CT+6)+'" text-anchor="end">'+sg(Math.round(chi-cp))+'</text>');
  bars.forEach(function(b,i){
    var x=X(i).toFixed(1),cl=b.c>=b.o?P+'-cu':P+'-cd',y1=Y(Math.max(b.o,b.c)),y2=Y(Math.min(b.o,b.c));
    g.push('<line class="'+cl+'" x1="'+x+'" y1="'+Y(b.h).toFixed(1)+'" x2="'+x+'" y2="'+Y(b.l).toFixed(1)+'"/><rect class="'+cl+'" x="'+(X(i)-2).toFixed(1)+'" y="'+y1.toFixed(1)+'" width="4" height="'+Math.max(.8,y2-y1).toFixed(1)+'"/>');
  });
  var pts=cvd.map(function(v,i){return X(i).toFixed(1)+','+YC(v).toFixed(1);});
  g.push('<polygon class="'+P+'-ar" points="'+X(0).toFixed(1)+','+zy+' '+pts.join(' ')+' '+X(n-1).toFixed(1)+','+zy+'"/><polyline class="'+P+'-ln" points="'+pts.join(' ')+'"/>');
  var H=bars.map(function(b){return b.h;}),L=bars.map(function(b){return b.l;});
  var ph=pivots(H,true),pl=pivots(L,false),dv=null;
  if(ph.length>1){var a=ph[ph.length-2],b=ph[ph.length-1];if(b-a>=4&&H[b]>H[a]&&cvd[b]<cvd[a])dv={k:'bear',a:a,b:b,p:H};}
  if(pl.length>1){var a2=pl[pl.length-2],b2=pl[pl.length-1];if(b2-a2>=4&&L[b2]<L[a2]&&cvd[b2]>cvd[a2]&&(!dv||b2>dv.b))dv={k:'bull',a:a2,b:b2,p:L};}
  if(dv){
    var lc=dv.k==='bear'?P+'-dvb':P+'-dvu',pc=dv.k==='bear'?P+'-pb':P+'-pu';
    [[Y(dv.p[dv.a]),Y(dv.p[dv.b])],[YC(cvd[dv.a]),YC(cvd[dv.b])]].forEach(function(q,m){
      var dy=dv.k==='bear'?-3:3;
      g.push('<line class="'+lc+'" x1="'+X(dv.a).toFixed(1)+'" y1="'+(q[0]+(m?0:dy)).toFixed(1)+'" x2="'+X(dv.b).toFixed(1)+'" y2="'+(q[1]+(m?0:dy)).toFixed(1)+'"/>');
      g.push('<circle class="'+pc+'" cx="'+X(dv.a).toFixed(1)+'" cy="'+(q[0]+(m?0:dy)).toFixed(1)+'" r="1.6"/><circle class="'+pc+'" cx="'+X(dv.b).toFixed(1)+'" cy="'+(q[1]+(m?0:dy)).toFixed(1)+'" r="1.6"/>');
    });
    g.push('<text class="'+P+'-lbl '+pc+'" x="'+X(dv.a).toFixed(1)+'" y="'+(dv.k==='bear'?T+6:PB-2)+'">'+(dv.k==='bear'?'BEAR DIV ▼':'BULL DIV ▲')+'</text>');
  }
  var lb=bars[n-1];
  g.push('<text class="'+P+'-tlast" x="298" y="'+(Y(lb.c)+2.5).toFixed(1)+'" text-anchor="end">◂'+lb.c.toFixed(2)+'</text>');
  [0,10,20,30].forEach(function(i){if(i<n)g.push('<text x="'+(i?X(i).toFixed(1):0)+'" y="164" text-anchor="'+(i?'middle':'start')+'">'+hm(bars[i].t)+'</text>');});
  svg.innerHTML=g.join('');
  if(dv){
    var v1=dv.p[dv.a].toFixed(2),v2=dv.p[dv.b].toFixed(2);
    sigEl.className=P+'-sig '+P+'-'+dv.k;
    sigEl.innerHTML=dv.k==='bear'?'<b>BEAR DIV ▼</b> px HH '+v2+' &gt; '+v1+' &middot; CVD LH '+sg(cvd[dv.b])+' &lt; '+sg(cvd[dv.a]):'<b>BULL DIV ▲</b> px LL '+v2+' &lt; '+v1+' &middot; CVD HL '+sg(cvd[dv.b])+' &gt; '+sg(cvd[dv.a]);
  }else{sigEl.className=P+'-sig';sigEl.innerHTML='<b>NO DIVERGENCE</b> &middot; price and CVD swings confirm';}
  var bd=lb.buy-lb.sell,cv=cvd[n-1];
  function cls(x){return x>0?P+'-up':x<0?P+'-dn':'';}
  rd.innerHTML='<span>LAST<b>'+lb.c.toFixed(2)+'</b></span><span>BAR &Delta;<b class="'+cls(bd)+'">'+sg(bd)+'</b></span><span>CVD<b class="'+cls(cv)+'">'+sg(cv)+'</b></span>'+
    '<span>BUY<b>'+cm(tb)+'</b></span><span>SELL<b>'+cm(ts)+'</b></span><span>&Delta;/VOL<b class="'+cls(cv)+'">'+(Math.abs(cv/(tb+ts)*100)<.0005?'':cv>0?'+':'−')+Math.abs(cv/(tb+ts)*100).toFixed(3)+'%</b></span>';
}
var paused=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches),ticks=0,acc=0,lastT=0;
function setP(p){paused=p;btn.setAttribute('aria-pressed',p?'true':'false');btn.querySelector('span').textContent=p?'PAUSED':'LIVE';}
function step(){
  var L=bars[bars.length-1],anc=71.58+.12*Math.sin(ticks/45);
  var mv=Math.round((rnd()-.5)*3.2+(anc-L.c)*6);mv=Math.max(-3,Math.min(3,mv));
  var q=Math.round(18+rnd()*150),up=mv>0||(mv===0&&rnd()<.5),bq=Math.round(q*(up?.6+rnd()*.25:.15+rnd()*.25));
  L.c=r2(L.c+mv*TK);L.h=Math.max(L.h,L.c);L.l=Math.min(L.l,L.c);L.buy+=bq;L.sell+=q-bq;
  ticks++;
  if(ticks%10===0){
    bars.push({t:L.t+1,o:L.c,h:L.c,l:L.c,c:L.c,buy:0,sell:0});
    if(bars.length>WIN){var x=bars.shift();base.buy+=x.buy;base.sell+=x.sell;}
  }
  draw();
}
function loop(ts){
  if (!root.isConnected) return;
  if(!lastT)lastT=ts;acc+=ts-lastT;lastT=ts;
  if(acc>700){acc=0;if(!paused)step();}
  requestAnimationFrame(loop);
}
btn.addEventListener('click',function(){setP(!paused);});
root.addEventListener('keydown',function(e){if(e.key===' '&&e.target===root){e.preventDefault();setP(!paused);}});
setP(paused);draw();requestAnimationFrame(loop);

