var P='cvp-pressure-split';
var rowsEl=root.querySelector('.'+P+'-rows'),det=root.querySelector('.'+P+'-det'),wb=root.querySelectorAll('.'+P+'-w');
var s=730019;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function fv(v){var a=Math.abs(v);return a>=1e6?(a/1e6).toFixed(2)+'M':a>=1e4?(a/1e3).toFixed(0)+'k':a>=1e3?(a/1e3).toFixed(1)+'k':String(a);}
function sgv(v){return (v>0?'+':v<0?'−':'±')+fv(v);}
function lr(parts){var t=0,f=[],r=0;parts.forEach(function(p){t+=p;});if(!t)return parts.map(function(){return 0;});
  parts.forEach(function(p,i){var x=p/t*100;f.push({i:i,fl:Math.floor(x),rm:x-Math.floor(x)});r+=Math.floor(x);});
  f.slice().sort(function(a,b){return b.rm-a.rm;}).slice(0,100-r).forEach(function(o){o.fl++;});return f.map(function(o){return o.fl;});}
var WN=['5 min','30 min','session 09:30–13:42'];
var SY=[['NVDA',186e6,.57],['AAPL',51e6,.47],['MSFT',19e6,.53],['AMZN',41e6,.44],['META',12e6,.51],['TSLA',96e6,.39],['AMD',48e6,.55],['AVGO',22e6,.49]];
var BK=['<$10k','$10–100k','$100k–1M','≥$1M'],BW=[.41,.33,.18,.08];
function split(total,ws){var out=[],used=0,W=0;ws.forEach(function(w){W+=w;});for(var i=0;i<ws.length;i++){var v=i<ws.length-1?Math.round(total*ws[i]/W/100)*100:total-used;out.push(v);used+=v;}return out;}
var data=SY.map(function(q){
  var w=[q[1]*.009*(0.7+rnd()*.6),q[1]*.055*(0.8+rnd()*.4),q[1]*.47*(0.85+rnd()*.3)];
  return {sym:q[0],win:w.map(function(V,k){
    V=Math.round(V/100)*100;
    var bf=Math.min(.72,Math.max(.26,q[2]+(rnd()-.5)*(k===0?.26:k===1?.14:.06))),mf=.06+rnd()*.08;
    var buy=Math.round(V*bf*(1-mf)/100)*100,mid=Math.round(V*mf/100)*100,sell=V-buy-mid;
    var tilt=[1-(bf-.5)*.4,1,1+(bf-.5)*.5,1+(bf-.5)*1.1];
    return {V:V,buy:buy,mid:mid,sell:sell,
      bb:split(buy,BW.map(function(x,i){return x*tilt[i];})),
      bs:split(sell,BW.map(function(x,i){return x*(2-tilt[i]);})),
      bm:split(mid,BW)};
  })};
});
var w=2,selSym='NVDA';
function press(r){return (r.buy-r.sell)/(r.buy+r.sell);}
function draw(){
  var list=data.slice().sort(function(a,b){return press(b.win[w])-press(a.win[w]);});
  rowsEl.innerHTML=list.map(function(d){
    var r=d.win[w],p=lr([r.buy,r.mid,r.sell]),net=r.buy-r.sell,ratio=r.buy/r.sell;
    var nc=net>0?P+'-up':net<0?P+'-dn':'',ar=net>0?'▲':net<0?'▼':'◆';
    return '<div class="'+P+'-row'+(d.sym===selSym?' '+P+'-sel':'')+'" role="option" aria-selected="'+(d.sym===selSym)+'" data-s="'+d.sym+'" aria-label="'+d.sym+' buy '+p[0]+' percent, mid '+p[1]+', sell '+p[2]+', net '+sgv(net)+' shares">'+
      '<span class="'+P+'-sym">'+d.sym+'</span>'+
      '<span class="'+P+'-bar"><i class="'+P+'-b" style="flex:0 0 '+p[0]+'%">'+(p[0]>=14?p[0]:'')+'</i><i class="'+P+'-m" style="flex:0 0 '+p[1]+'%">'+(p[1]>=9?p[1]:'')+'</i><i class="'+P+'-s" style="flex:0 0 '+p[2]+'%">'+(p[2]>=14?p[2]:'')+'</i></span>'+
      '<span class="'+P+'-n '+nc+'">'+ar+sgv(net)+'</span><span class="'+P+'-r '+nc+'">'+ratio.toFixed(2)+'</span></div>';
  }).join('');
  var d=data.filter(function(x){return x.sym===selSym;})[0],r=d.win[w],pr=press(r)*100;
  var h='<div class="'+P+'-dh"><span><b>'+d.sym+'</b> '+WN[w]+'</span><span>VOL <b>'+fv(r.V)+'</b></span></div><div class="'+P+'-dh"><span>&#9650;B <b class="'+P+'-up">'+fv(r.buy)+'</b> &middot; &#9670;M <b>'+fv(r.mid)+'</b> &middot; &#9660;S <b class="'+P+'-dn">'+fv(r.sell)+'</b></span></div><div class="'+P+'-dr '+P+'-dcol"><span>NOTIONAL</span><span>SHARE</span><span>BUY vs SELL</span><span>%B</span></div>';
  var sh=lr(BK.map(function(_,i){return r.bb[i]+r.bs[i]+r.bm[i];}));
  BK.forEach(function(lbl,i){
