var ths=root.querySelectorAll('.'+P+'-th button');
var s=118033;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function fv(v){return v>=1e7?(v/1e6).toFixed(1)+'M':v>=1e6?(v/1e6).toFixed(2)+'M':(v/1e3).toFixed(0)+'k';}
var CURVE=[13.2,8.9,7.4,6.3,5.6,5.0,4.7,4.8,5.2,5.8,6.6,8.1,18.4];
var NOWB=4,NOWF=.5,cum=[0],i;
for(i=0;i<CURVE.length;i++)cum.push(cum[i]+CURVE[i]);
var FR=(cum[NOWB]+CURVE[NOWB]*NOWF)/100;
ex.innerHTML='curve to now <b>'+(FR*100).toFixed(1)+'%</b> of ADV';
var U=[['SMCI',24.6e6,3.42,'earnings 07:00'],['PLTR',61.8e6,2.58,'index add'],['COIN',9.4e6,2.11,'BTC +4.2%'],['MSTR',11.2e6,1.74,''],['AMD',48.3e6,1.31,''],['NVDA',186.4e6,1.08,''],['TSLA',96.1e6,0.97,''],['AAPL',51.2e6,0.83,''],['JPM',9.1e6,0.74,''],['XOM',15.7e6,0.58,'']];
var rows=U.map(function(q){
  var adv=Math.round(q[1]/1e4)*1e4,vol=Math.round(adv*FR*q[2]/100)*100,exp=Math.round(adv*FR/100)*100;
  var w=[],tot=0;
