  var path=[0],acc=0;w.forEach(function(x){acc+=vol*x/tot;path.push(acc);});
  return {sym:q[0],adv:adv,vol:vol,exp:exp,rv:vol/exp,cat:q[3],path:path};
});
var key='r',sel='SMCI';
