function draw(){
  var L=sorted();
  body.innerHTML=L.map(function(r){
    var t=tier(r.rv),wd=Math.min(100,r.rv/3*100);
    return '<div class="'+P+'-row'+(r.sym===sel?' '+P+'-sel':'')+'" role="option" aria-selected="'+(r.sym===sel)+'" data-s="'+r.sym+'">'+
      '<span class="'+P+'-sym">'+r.sym+'</span><span class="'+P+'-num">'+fv(r.vol)+'</span><span class="'+P+'-num">'+fv(r.exp)+'</span>'+
