  r.path.forEach(function(v,k){var xx=k<=NOWB?k:NOWB+NOWF;td.push(X(xx).toFixed(1)+','+Y(v).toFixed(1));});
  var nx=X(NOWB+NOWF).toFixed(1),pj=[];
  for(i=NOWB+1;i<=13;i++)pj.push(X(i).toFixed(1)+','+Y(r.vol*cum[i]/100/FR).toFixed(1));
  g.push('<line class="'+P+'-ax" x1="4" y1="44" x2="106" y2="44"/><line class="'+P+'-nw" x1="'+nx+'" y1="3" x2="'+nx+'" y2="44"/>');
  g.push('<polyline class="'+P+'-ex" points="'+e.join(' ')+'"/><polyline class="'+P+'-pj" points="'+td[td.length-1]+' '+pj.join(' ')+'"/><polyline class="'+P+'-td" points="'+td.join(' ')+'"/>');
  g.push('<text x="4" y="50">09:30</text><text x="106" y="50" text-anchor="end">16:00</text>');
  svg.innerHTML=g.join('');
  var fl=t==='hot'?'UNUSUAL':t==='warm'?'ELEVATED':t==='thin'?'THIN':'NORMAL';
  dt.innerHTML='<b>'+r.sym+'</b> <span class="'+P+'-flag'+(t?' '+P+'-'+t:'')+'">'+fl+'</span>'+(r.cat?' <span>'+r.cat+'</span>':'')+
    '<br>VOL <b>'+r.vol.toLocaleString('en-US')+'</b> vs EXP <b>'+r.exp.toLocaleString('en-US')+'</b>'+
    '<br>RVOL <b>'+r.rv.toFixed(2)+'&times;</b> &middot; %ADV <b>'+(r.vol/r.adv*100).toFixed(1)+'%</b>'+
    '<br>proj. close <b>'+fv(proj)+'</b> = <b>'+(proj/r.adv).toFixed(2)+'&times;</b> ADV '+fv(r.adv);
  return L;
}
var cur=draw();
function setKey(k){key=k;cur=draw();}
ths.forEach(function(b){b.addEventListener('click',function(){setKey(b.getAttribute('data-k'));});});
