  var dr=i<10?.16:i<34?-.09:i<60?.07:.01;
  var o=px,c=r2(o+dr+(rnd()-.5)*.42),h=r2(Math.max(o,c)+rnd()*.14),l=r2(Math.min(o,c)-rnd()*.14);
