var thr=5,sel=0;
function vis(){return prints.map(function(p,k){p.k=k;return p;}).filter(function(p){return p.n>=thr*1e6;});}
function draw(){
  var V=vis();if(sel>=V.length)sel=V.length-1;if(sel<0)sel=0;
  var lo=1e9,hi=-1e9;bars.forEach(function(b){lo=Math.min(lo,b.l);hi=Math.max(hi,b.h);});
  var pd=(hi-lo)*.1;lo-=pd;hi+=pd;
  var X1=262,T=6,B=108,VB=126;
  function X(j){return 2+j*(X1-4)/(N-1);}function Y(p){return T+(hi-p)/(hi-lo)*(B-T);}
  var g=[],st=(hi-lo)>6?2:(hi-lo)>2.5?1:.5,mv=0,vy=Y(vw[N-1]);bars.forEach(function(b){mv=Math.max(mv,b.v);});
  for(var gp=Math.ceil(lo/st)*st;gp<=hi;gp+=st){var gy=Y(gp);g.push('<line class="'+P+'-grid" x1="0" y1="'+gy.toFixed(1)+'" x2="'+X1+'" y2="'+gy.toFixed(1)+'"/>'+(Math.abs(gy-vy)<9?'':'<text x="298" y="'+(gy+2.5).toFixed(1)+'" text-anchor="end">'+gp.toFixed(st<1?1:0)+'</text>'));}
  bars.forEach(function(b,j){var vh=b.v/mv*14;g.push('<rect class="'+P+'-vol" x="'+(X(j)-1.1).toFixed(1)+'" y="'+(VB-vh).toFixed(1)+'" width="2.2" height="'+vh.toFixed(1)+'"/>');});
  g.push('<polyline class="'+P+'-vw" points="'+vw.map(function(v,j){return X(j).toFixed(1)+','+Y(v).toFixed(1);}).join(' ')+'"/>');
  g.push('<polyline class="'+P+'-px" points="'+bars.map(function(b,j){return X(j).toFixed(1)+','+Y(b.c).toFixed(1);}).join(' ')+'"/>');
  g.push('<text class="'+P+'-vwl" x="298" y="'+(vy+2.5).toFixed(1)+'" text-anchor="end">VWAP '+vw[N-1].toFixed(2)+'</text>');
  V.slice().sort(function(a,b){return b.n-a.n;}).forEach(function(p){
    var r=2.2+Math.sqrt(p.n/1e6)*2.1,cls=p.side==='B'?P+'-bb':p.side==='S'?P+'-bs':P+'-bm';
    var cx=X(p.bar+p.sec/120).toFixed(1),cy=Y(p.px).toFixed(1);
    g.push('<circle class="'+P+'-bub '+cls+(p.venue==='TRF'?' '+P+'-dk':'')+'" data-k="'+p.k+'" cx="'+cx+'" cy="'+cy+'" r="'+r.toFixed(1)+'"/>');
    if(r>8)g.push('<text class="'+P+'-num" x="'+cx+'" y="'+(+cy+2.2)+'" text-anchor="middle">'+Math.round(p.n/1e6)+'</text>');
  });
  if(V.length){var sp=V[sel],rr=2.2+Math.sqrt(sp.n/1e6)*2.1;g.push('<circle class="'+P+'-ring" cx="'+X(sp.bar+sp.sec/120).toFixed(1)+'" cy="'+Y(sp.px).toFixed(1)+'" r="'+(rr+1.5).toFixed(1)+'"/>');}
  [0,30,60,89].forEach(function(j){g.push('<text x="'+X(j).toFixed(1)+'" y="136" text-anchor="'+(j===0?'start':j===89?'end':'middle')+'">'+hm(570+j*2+(j===89?2:0))+'</text>');});
  svg.innerHTML=g.join('');
  tb.forEach(function(b){var on=+b.getAttribute('data-t')===thr;b.classList.toggle(P+'-on',on);b.setAttribute('aria-pressed',on?'true':'false');});
  if(!V.length){rd.innerHTML='No prints at this threshold';agg.innerHTML='';return;}
  var p=V[sel],t=570+p.bar*2,vwp=vw[p.bar],bp=(p.px-vwp)/vwp*1e4;
  var sc=p.side==='B'?P+'-up':p.side==='S'?P+'-dn':P+'-mid',sl=p.side==='B'?'▲ BUY @ask':p.side==='S'?'▼ SELL @bid':'◆ MID';
  var mm=t+Math.floor(p.sec/60),ss=p.sec%60;
  rd.innerHTML='<b>#'+(sel+1)+'/'+V.length+'</b> '+hm(mm)+':'+(ss<10?'0':'')+ss+' &middot; <span class="'+sc+'">'+sl+'</span> <b>'+cm(p.sz)+'</b> @ <b>'+p.px.toFixed(2)+'</b> = <b>$'+(p.n/1e6).toFixed(2)+'M</b>'+
    '<br>'+(p.venue==='TRF'?'FINRA TRF (off-exch)':p.venue)+' &middot; '+(p.sz/ADV*100).toFixed(3)+'% ADV &middot; '+(bp>=0?'+':'&minus;')+Math.abs(bp).toFixed(1)+' bp vs VWAP '+vwp.toFixed(2);
  var nb=0,ns=0,nm=0,sh=0,nn=0;
  V.forEach(function(q){nn+=q.n;sh+=q.sz;if(q.side==='B')nb+=q.n;else if(q.side==='S')ns+=q.n;else nm+=q.n;});
  var net=nb-ns;
  agg.innerHTML='&ge;$'+thr+'M: <b>'+V.length+'</b> prints &middot; <b>$'+(nn/1e6).toFixed(1)+'M</b> = <b>'+(nn/sn*100).toFixed(2)+'%</b> of $'+(sn/1e9).toFixed(2)+'B session &middot; B <b class="'+P+'-up">$'+(nb/1e6).toFixed(1)+'M</b> S <b class="'+P+'-dn">$'+(ns/1e6).toFixed(1)+'M</b> M <b>$'+(nm/1e6).toFixed(1)+'M</b> &middot; net <b class="'+(net>=0?P+'-up':P+'-dn')+'">'+(net>=0?'+':'&minus;')+'$'+Math.abs(net/1e6).toFixed(1)+'M</b>';
}
function setT(t){var V=vis(),cur=V[sel]?V[sel].k:-1;thr=t;V=vis();sel=0;V.forEach(function(p,k){if(p.k===cur)sel=k;});draw();}
tb.forEach(function(b){b.addEventListener('click',function(){setT(+b.getAttribute('data-t'));});});
svg.addEventListener('click',function(e){var c=e.target.closest('.'+P+'-bub');if(!c)return;var k=+c.getAttribute('data-k');vis().forEach(function(p,j){if(p.k===k)sel=j;});draw();});
root.addEventListener('keydown',function(e){
  var n=vis().length;
  if(e.key==='ArrowRight'){e.preventDefault();sel=(sel+1)%Math.max(1,n);draw();}
  else if(e.key==='ArrowLeft'){e.preventDefault();sel=(sel-1+Math.max(1,n))%Math.max(1,n);draw();}
  else if(e.key==='1')setT(1);else if(e.key==='2')setT(5);else if(e.key==='3')setT(10);
});
draw();

css:
.cvp-intraday-curve{--up:#3EE28A;--dn:#FF6B7A;--am:#FFC24D;--ac:#6EA8FF;box-sizing:border-box;width:100%;max-width:400px;background:#0B0F17;border:1px solid #1C2432;border-radius:10px;padding:9px 9px 7px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:8.5px;color:#8B98B0;font-variant-numeric:tabular-nums;outline:none}
.cvp-intraday-curve *{box-sizing:border-box}
.cvp-intraday-curve:focus-visible{box-shadow:0 0 0 2px rgba(110,168,255,.5)}
.cvp-intraday-curve-hd{display:flex;justify-content:space-between;align-items:baseline;gap:6px;margin-bottom:4px}
.cvp-intraday-curve-sym{font:700 11px/1.2 system-ui,-apple-system,Segoe UI,sans-serif;color:#E4EBF7;letter-spacing:.03em}
.cvp-intraday-curve-sym b{font:500 7.5px ui-monospace,Menlo,Consolas,monospace;color:#56627C;letter-spacing:.04em;margin-left:3px}
.cvp-intraday-curve-ord{flex:none;padding:1px 5px;font-size:7.5px;font-weight:700;letter-spacing:.06em;color:var(--up);border:1px solid rgba(62,226,138,.4);border-radius:3px;white-space:nowrap}
.cvp-intraday-curve-svg{display:block;width:100%;height:auto;cursor:pointer}
.cvp-intraday-curve-svg text{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:7px;fill:#56627C}
.cvp-intraday-curve-grid{stroke:#161E2B;stroke-width:.7}
.cvp-intraday-curve-hs{fill:none;stroke:#7C8AA5;stroke-width:.9;stroke-dasharray:2 1.5}
.cvp-intraday-curve-td{fill:rgba(110,168,255,.55)}
.cvp-intraday-curve-td.cvp-intraday-curve-hot{fill:rgba(255,194,77,.7)}
.cvp-intraday-curve-pt{stroke:rgba(110,168,255,.6);stroke-width:.6}
.cvp-intraday-curve-fl{fill:var(--up)}
.cvp-intraday-curve-sel{fill:rgba(228,235,247,.06);stroke:rgba(228,235,247,.3);stroke-width:.6}
.cvp-intraday-curve-now{stroke:var(--am);stroke-width:.8;stroke-dasharray:2 2}
.cvp-intraday-curve-svg .cvp-intraday-curve-nt{fill:var(--am)}
.cvp-intraday-curve-sep{stroke:#2A3650;stroke-width:.8}
.cvp-intraday-curve-read{min-height:30px;margin-top:3px;padding:4px 6px;background:#0F1520;border:1px solid #1C2432;border-radius:5px;line-height:1.5;color:#93A2BC;font-size:8px}
.cvp-intraday-curve-read b{color:#E4EBF7;font-weight:600}
.cvp-intraday-curve-up{color:var(--up)}
.cvp-intraday-curve-dn{color:var(--dn)}
.cvp-intraday-curve-sch{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin-top:4px;background:#1C2432;border:1px solid #1C2432;border-radius:4px;overflow:hidden}
.cvp-intraday-curve-sch span{display:flex;flex-direction:column;gap:1px;padding:3px 4px;background:#0B0F17;font-size:6.5px;letter-spacing:.08em;color:#56627C}
.cvp-intraday-curve-sch b{font-size:8.5px;letter-spacing:0;color:#E4EBF7;font-weight:600;text-align:right}
.cvp-intraday-curve-sch b.cvp-intraday-curve-up{color:var(--up)}
.cvp-intraday-curve-sch b.cvp-intraday-curve-dn{color:var(--dn)}
.cvp-intraday-curve-ft{display:flex;flex-wrap:wrap;gap:3px 8px;margin-top:5px;font-size:6.5px;letter-spacing:.06em;color:#4B5772}
.cvp-intraday-curve-ft i{display:inline-block;width:8px;height:5px;margin-right:3px;vertical-align:middle;border-radius:1px}
.cvp-intraday-curve-kh{border:1px dashed #7C8AA5}
.cvp-intraday-curve-kt{background:rgba(110,168,255,.55)}
.cvp-intraday-curve-kx{background:rgba(255,194,77,.7)}
.cvp-intraday-curve-kf{background:var(--up);height:2px}
.cvp-intraday-curve-keys{margin-left:auto}
@media (prefers-reduced-motion: reduce){.cvp-intraday-curve,.cvp-intraday-curve *{transition:none;animation:none}}

js:
var P='cvp-intraday-curve';
var svg=root.querySelector('.'+P+'-svg'),rd=root.querySelector('.'+P+'-read'),sch=root.querySelector('.'+P+'-sch');
var s=305917;function rnd(){s=(s*16807)%2147483647;return (s-1)/2147483646;}
function cm(n){var a=Math.abs(n);return (n<0?'−':'')+String(a).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function hm(m){var h=Math.floor(m/60),mm=m%60;return (h<10?'0':'')+h+':'+(mm<10?'0':'')+mm;}
var HIST=[13.2,8.9,7.4,6.3,5.6,5.0,4.7,4.8,5.2,5.8,6.6,8.1,9.6,8.8];
var NB=HIST.length,ADV=41800000,ORD=250000,NOWB=7,NOWF=10/30;
function lab(b){return b===13?'CLOSE X':hm(570+b*30)+'–'+hm(600+b*30);}
var tgt=[],used=0,fr=[],b;
for(b=0;b<NB;b++){var x=ORD*HIST[b]/100;tgt.push(Math.floor(x));fr.push({b:b,r:x-Math.floor(x)});used+=Math.floor(x);}
fr.sort(function(a,c){return c.r-a.r;}).slice(0,ORD-used).forEach(function(o){tgt[o.b]++;});
var mkt=[],fill=[],vwp=[],apx=[],px=186.20;
for(b=0;b<NB;b++){
  if(b>NOWB){mkt.push(null);fill.push(0);vwp.push(null);apx.push(null);continue;}
  var part=b===NOWB?NOWF:1,f=(b===0?1.28:1.06+rnd()*.22);
  var mv=Math.round(ADV*HIST[b]/100*f*part/100)*100;
  var fq=Math.round(tgt[b]*part*(0.955+rnd()*.09)/100)*100;
  px+=(rnd()-.45)*.9;var vw=Math.round(px*1000)/1000,ap=Math.round((vw+(rnd()-.55)*.06)*10000)/10000;
  mkt.push(mv);fill.push(fq);vwp.push(vw);apx.push(ap);
}
var sel=NOWB,HID='cvp-intraday-curve-hatch-'+Math.floor(Math.random()*1e9).toString(36);
var X0=4,X1=262,T=6,B=104,gap=4,cw=(X1-X0-gap)/NB;
function X(b){return X0+b*cw+(b===13?gap:0);}
var ymax=18;function Y(v){return B-v/ymax*(B-T);}
function draw(){
  var g=['<defs><pattern id="'+HID+'" width="3" height="3" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="1.2" height="3" fill="rgba(110,168,255,.55)"/></pattern></defs>'];
  [0,5,10,15].forEach(function(v){var y=Y(v).toFixed(1);g.push('<line class="'+P+'-grid" x1="'+X0+'" y1="'+y+'" x2="'+X1+'" y2="'+y+'"/><text x="298" y="'+(+y+2.5)+'" text-anchor="end">'+v+'%</text>');});
  g.push('<rect class="'+P+'-sel" x="'+(X(sel)+.3).toFixed(1)+'" y="'+T+'" width="'+(cw-.6).toFixed(1)+'" height="'+(B-T+14)+'"/>');
  for(b=0;b<NB;b++){
    var x=X(b)+1.4,w=cw-2.8;
    if(mkt[b]!==null){
      var tp=mkt[b]/ADV*100,cls=b===NOWB?P+'-pt':P+'-td'+(tp/HIST[b]>=1.2?' '+P+'-hot':'');
      g.push('<rect class="'+cls+'"'+(b===NOWB?' fill="url(#'+HID+')"':'')+' x="'+x.toFixed(1)+'" y="'+Y(tp).toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+(B-Y(tp)).toFixed(1)+'"/>');
      g.push('<rect class="'+P+'-fl" x="'+x.toFixed(1)+'" y="'+(B+2).toFixed(1)+'" width="'+(w*Math.min(1,fill[b]/tgt[b])).toFixed(1)+'" height="2"/>');
    }
    g.push('<rect class="'+P+'-hs" x="'+x.toFixed(1)+'" y="'+Y(HIST[b]).toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+(B-Y(HIST[b])).toFixed(1)+'"/>');
  }
  var nx=(X(NOWB)+cw*NOWF).toFixed(1);
  g.push('<line class="'+P+'-now" x1="'+nx+'" y1="'+(T+8)+'" x2="'+nx+'" y2="'+(B+5)+'"/><text class="'+P+'-nt" x="'+nx+'" y="'+(T+5)+'" text-anchor="middle">NOW 13:10</text>');
  var sx=(X(13)-gap/2).toFixed(1);g.push('<line class="'+P+'-sep" x1="'+sx+'" y1="'+T+'" x2="'+sx+'" y2="'+(B+5)+'"/>');
  [[0,'09:30'],[5,'12:00'],[9,'14:00'],[13,'CLX']].forEach(function(q){g.push('<text x="'+(X(q[0])+(q[0]===13?cw/2:0)).toFixed(1)+'" y="120" text-anchor="'+(q[0]===13?'middle':'start')+'">'+q[1]+'</text>');});
  svg.innerHTML=g.join('');
  var h='<b>'+lab(sel)+'</b> &middot; 20d <b>'+HIST[sel].toFixed(1)+'%</b>';
  if(mkt[sel]!==null){
    var tp2=mkt[sel]/ADV*100,rt=tp2/(HIST[sel]*(sel===NOWB?NOWF:1)),pov=fill[sel]/mkt[sel]*100,sl=(apx[sel]-vwp[sel])/vwp[sel]*1e4;
    h+=' &middot; today <b>'+tp2.toFixed(2)+'%</b> '+(sel===NOWB?'(10/30m) ':'')+'<span class="'+(rt>=1?P+'-up':P+'-dn')+'">'+(rt>=1?'▲':'▼')+rt.toFixed(2)+'&times;</span>'+
      '<br>mkt <b>'+cm(mkt[sel])+'</b> &middot; tgt <b>'+cm(tgt[sel])+'</b>'+(sel===NOWB?' ('+cm(Math.round(tgt[sel]*NOWF))+' due)':'')+' &middot; fill <b>'+cm(fill[sel])+'</b> &middot; POV <b>'+pov.toFixed(2)+'%</b>'+
      '<br>avg <b>'+apx[sel].toFixed(4)+'</b> vs iVWAP <b>'+vwp[sel].toFixed(3)+'</b> &rarr; <span class="'+(sl<=0?P+'-up':P+'-dn')+'">'+(sl>0?'+':sl<0?'&minus;':'&plusmn;')+Math.abs(sl).toFixed(1)+' bp '+(sl<=0?'better':'worse')+'</span>';
  }else{
    h+=' &middot; scheduled <b>'+cm(tgt[sel])+'</b> sh ('+(tgt[sel]/ORD*100).toFixed(2)+'% of order)<br><span>not started &mdash; expected mkt '+cm(Math.round(ADV*HIST[sel]/100/100)*100)+' at 20d curve</span>';
  }
  rd.innerHTML=h;
}
var F=0,S=0,MV=0,NF=0,NM=0;
for(b=0;b<=NOWB;b++){F+=fill[b];S+=tgt[b]*(b===NOWB?NOWF:1);MV+=mkt[b];NF+=fill[b]*apx[b];NM+=mkt[b]*vwp[b];}
S=Math.round(S);
var AV=NF/F,IV=NM/MV,SL=(AV-IV)/IV*1e4,DV=F-S;
sch.innerHTML='<span>FILLED<b>'+cm(F)+'</b></span><span>SCHED<b>'+cm(S)+'</b></span><span>'+(DV>=0?'AHEAD':'BEHIND')+'<b class="'+(DV>=0?P+'-up':P+'-dn')+'">'+(DV>0?'+':'')+cm(DV)+'</b></span><span>LEAVES<b>'+cm(ORD-F)+'</b></span>'+
  '<span>% DONE<b>'+(F/ORD*100).toFixed(1)+'%</b></span><span>POV<b>'+(F/MV*100).toFixed(2)+'%</b></span><span>AVG PX<b>'+AV.toFixed(4)+'</b></span><span>vs iVWAP<b class="'+(SL<=0?P+'-up':P+'-dn')+'">'+(SL>0?'+':SL<0?'−':'')+Math.abs(SL).toFixed(1)+'bp</b></span>';
function setB(v){sel=Math.max(0,Math.min(NB-1,v));draw();}
root.addEventListener('keydown',function(e){
  if(e.key==='ArrowLeft'){e.preventDefault();setB(sel-1);}else if(e.key==='ArrowRight'){e.preventDefault();setB(sel+1);}
  else if(e.key==='Home'){e.preventDefault();setB(0);}else if(e.key==='End'){e.preventDefault();setB(NB-1);}
});
svg.addEventListener('click',function(e){var r=svg.getBoundingClientRect();if(!r.width)return;var xx=(e.clientX-r.left)/r.width*300;for(var k=NB-1;k>=0;k--){if(xx>=X(k)){setB(k);return;}}setB(0);});
draw();
